def has_symbol(username :str, password:str, symbols:list) -> int:
    """ return int 
            the int is the count of the number of sybbols in the password"""
    symbols_count = 0          
    for i in password:
        if i in symbols: symbols_count += 1
    if symbols_count == 0:
        print("you need the correct symbols")
    return symbols_count

